insert into regions ("region_id", "region_name", "parent_region_id", "region_type", "priority", "coverage_reason", "known_bias_risk", "language_scope", "script_scope", "source_strategy", "notes") values ('REG007', 'East Asia', null, 'macro_region', 'Launch', 'Necessary as a transnational frame for China, Japan, Korea, Taiwan, Hong Kong, and regional visual circulation.', 'Risk of flattening distinct histories into a single regional label.', 'Chinese; Japanese; Korean; English; others', 'Han characters; Kana; Hangul; Latin', 'National libraries; museum collections; regional archives; periodicals; web archives; bilingual source registry.', 'Use as parent region only; most records should also have more specific country/city context.') on conflict ("region_id") do update set "region_name" = excluded."region_name", "parent_region_id" = excluded."parent_region_id", "region_type" = excluded."region_type", "priority" = excluded."priority", "coverage_reason" = excluded."coverage_reason", "known_bias_risk" = excluded."known_bias_risk", "language_scope" = excluded."language_scope", "script_scope" = excluded."script_scope", "source_strategy" = excluded."source_strategy", "notes" = excluded."notes";
