insert into regions ("region_id", "region_name", "parent_region_id", "region_type", "priority", "coverage_reason", "known_bias_risk", "language_scope", "script_scope", "source_strategy", "notes") values ('REG009', 'Hong Kong', 'REG007', 'city/territory_context', 'Launch', 'Important for bilingual typography, film and entertainment graphics, publishing, advertising, identity, protest graphics, and regional circulation.', 'Often folded into either British colonial or Chinese frameworks without local media specificity.', 'Chinese; Cantonese; English', 'Traditional Chinese; Latin', 'University archives; museum collections; film/poster archives; periodicals; web archives; community archives.', 'Needs distinct treatment because of bilingual, colonial, commercial, and activist visual cultures.') on conflict ("region_id") do update set "region_name" = excluded."region_name", "parent_region_id" = excluded."parent_region_id", "region_type" = excluded."region_type", "priority" = excluded."priority", "coverage_reason" = excluded."coverage_reason", "known_bias_risk" = excluded."known_bias_risk", "language_scope" = excluded."language_scope", "script_scope" = excluded."script_scope", "source_strategy" = excluded."source_strategy", "notes" = excluded."notes";
insert into regions ("region_id", "region_name", "parent_region_id", "region_type", "priority", "coverage_reason", "known_bias_risk", "language_scope", "script_scope", "source_strategy", "notes") values ('REG010', 'Taiwan', 'REG007', 'country/territory_context', 'Launch', 'Important for print modernization, political graphics, publishing, typography, identity, advertising, and contemporary digital culture.', 'Often absent from English-language frameworks or merged into broader Chinese design history.', 'Chinese; Taiwanese Hokkien; Japanese historical materials; English', 'Traditional Chinese; Kana in historical contexts; Latin', 'National libraries; museum archives; university repositories; periodicals; poster archives; web archives.', 'Needs separate tracking of Japanese colonial, postwar, democratization, and contemporary periods.') on conflict ("region_id") do update set "region_name" = excluded."region_name", "parent_region_id" = excluded."parent_region_id", "region_type" = excluded."region_type", "priority" = excluded."priority", "coverage_reason" = excluded."coverage_reason", "known_bias_risk" = excluded."known_bias_risk", "language_scope" = excluded."language_scope", "script_scope" = excluded."script_scope", "source_strategy" = excluded."source_strategy", "notes" = excluded."notes";
insert into regions ("region_id", "region_name", "parent_region_id", "region_type", "priority", "coverage_reason", "known_bias_risk", "language_scope", "script_scope", "source_strategy", "notes") values ('REG011', 'Southeast Asia', null, 'macro_region', 'Launch', 'Important for colonial print, multilingual typography, advertising, political graphics, tourism, publishing, and contemporary platform design.', 'Often nearly invisible in graphic design history surveys.', 'Indonesian; Malay; Thai; Vietnamese; Filipino languages; Khmer; Burmese; English; French; Dutch; Chinese; others', 'Latin; Thai; Khmer; Burmese; Han; Arabic-derived scripts; others', 'National libraries; colonial archives; university repositories; newspaper archives; museum collections; community archives.', 'Needs country-by-country decomposition.') on conflict ("region_id") do update set "region_name" = excluded."region_name", "parent_region_id" = excluded."parent_region_id", "region_type" = excluded."region_type", "priority" = excluded."priority", "coverage_reason" = excluded."coverage_reason", "known_bias_risk" = excluded."known_bias_risk", "language_scope" = excluded."language_scope", "script_scope" = excluded."script_scope", "source_strategy" = excluded."source_strategy", "notes" = excluded."notes";
insert into regions ("region_id", "region_name", "parent_region_id", "region_type", "priority", "coverage_reason", "known_bias_risk", "language_scope", "script_scope", "source_strategy", "notes") values ('REG012', 'South Asia', null, 'macro_region', 'Launch', 'Essential for multilingual typography, publishing, film graphics, political posters, state information design, advertising, and digital design.', 'Often reduced to craft, film posters, or postcolonial case studies.', 'Hindi; Bengali; Urdu; Tamil; Telugu; Malayalam; Marathi; Sinhala; Nepali; English; others', 'Devanagari; Bengali; Perso-Arabic; Tamil; Telugu; Malayalam; Latin; others', 'National libraries; film poster archives; university archives; newspaper archives; design schools; public information archives.', 'Must model multilingual script and typography as primary, not peripheral.') on conflict ("region_id") do update set "region_name" = excluded."region_name", "parent_region_id" = excluded."parent_region_id", "region_type" = excluded."region_type", "priority" = excluded."priority", "coverage_reason" = excluded."coverage_reason", "known_bias_risk" = excluded."known_bias_risk", "language_scope" = excluded."language_scope", "script_scope" = excluded."script_scope", "source_strategy" = excluded."source_strategy", "notes" = excluded."notes";
