insert into regions ("region_id", "region_name", "parent_region_id", "region_type", "priority", "coverage_reason", "known_bias_risk", "language_scope", "script_scope", "source_strategy", "notes") values ('REG014', 'Africa', null, 'macro_region', 'Launch', 'Essential for decolonial graphics, print cultures, political posters, publishing, advertising, vernacular commercial graphics, and contemporary digital design.', 'High risk of underrepresentation due to digitization and archive access gaps.', 'Arabic; English; French; Portuguese; Swahili; Amharic; Yoruba; Hausa; Zulu; Xhosa; others', 'Latin; Arabic; Ethiopic; others', 'National libraries; university archives; poster/political collections; newspaper archives; community archives; oral histories.', 'Should be decomposed regionally and nationally; avoid continent-as-single-category treatment.') on conflict ("region_id") do update set "region_name" = excluded."region_name", "parent_region_id" = excluded."parent_region_id", "region_type" = excluded."region_type", "priority" = excluded."priority", "coverage_reason" = excluded."coverage_reason", "known_bias_risk" = excluded."known_bias_risk", "language_scope" = excluded."language_scope", "script_scope" = excluded."script_scope", "source_strategy" = excluded."source_strategy", "notes" = excluded."notes";
