or_institution" = excluded."creator_or_institution", "date_text" = excluded."date_text", "record_family" = excluded."record_family", "rights_note" = excluded."rights_note", "recommended_image_zone" = excluded."recommended_image_zone", "recommended_status" = excluded."recommended_status", "reason" = excluded."reason";

