insert into capture_batch_cell_assignments ("capture_id", "source_id", "source_name", "source_title", "image_presence_code", "assigned_cell_id", "assigned_cell_name", "assignment_type", "assignment_confidence", "assignment_basis", "matched_terms", "recommended_next_step") values ('ECAP044', 'SRC006', 'Library of Congress loc.gov API', 'Production. The first of a series of production posters designed by the Office of Emergency Management for display in defense plants throughout the United States. The poster was designed for the OEM by Jean Carlu, eminent poster artist and graphic design expert. The poster measures 30 x 40 inches in size and was issued June 23, 1941', 'IMG04', 'PC02', 'World War public-information and propaganda posters', 'proposed_new_cell', 'high', 'keyword_rule', '\bOffice of Emergency Management\b', 'Create or confirm a public-information/war-propaganda poster cell.') on conflict ("capture_id") do update set "source_id" = excluded."source_id", "source_name" = excluded."source_name", "source_title" = excluded."source_title", "image_presence_code" = excluded."image_presence_code", "assigned_cell_id" = excluded."assigned_cell_id", "assigned_cell_name" = excluded."assigned_cell_name", "assignment_type" = excluded."assignment_type", "assignment_confidence" = excluded."assignment_confidence", "assignment_basis" = excluded."assignment_basis", "matched_terms" = excluded."matched_terms", "recommended_next_step" = excluded."recommended_next_step";
insert into capture_batch_cell_assignments ("capture_id", "source_id", "source_name", "source_title", "image_presence_code", "assigned_cell_id", "assigned_cell_name", "assignment_type", "assignment_confidence", "assignment_basis", "matched_terms", "recommended_next_step") values ('ECAP045', 'SRC006', 'Library of Congress loc.gov API', 'Poster. Men working together. A defense production poster for display in industrial plants throughout the nation. The poster, which measures 30 x 40 inches was designed and distributed by the Division of Information of the Office of War Information (OWI). The poster was issued November 18, 1941', 'IMG04', 'PC02', 'World War public-information and propaganda posters', 'proposed_new_cell', 'high', 'keyword_rule', '\bOffice of War Information\b', 'Create or confirm a public-information/war-propaganda poster cell.') on conflict ("capture_id") do update set "source_id" = excluded."source_id", "source_name" = excluded."source_name", "source_title" = excluded."source_title", "image_presence_code" = excluded."image_presence_code", "assigned_cell_id" = excluded."assigned_cell_id", "assigned_cell_name" = excluded."assigned_cell_name", "assignment_type" = excluded."assignment_type", "assignment_confidence" = excluded."assignment_confidence", "assignment_basis" = excluded."assignment_basis", "matched_terms" = excluded."matched_terms", "recommended_next_step" = excluded."recommended_next_step";
insert into capture_batch_cell_assignments ("capture_id", "source_id", "source_name", "source_title", "image_presence_code", "assigned_cell_id", "assigned_cell_name", "assignment_type", "assignment_confidence", "assignment_basis", "matched_terms", "recommended_next_step") values ('ECAP046', 'SRC006', 'Library of Congress loc.gov API', 'Civilian defense poster. "Jerry", the American eagle, which posed for this striking poster, is a resident of the National Zoological Park, Washington, D.C. The poster, in four colors, was issued today to illustrate Civilian Defense Week, observance of which begins Armistice Day, November 11, by proclamation of President Roosevelt. Specific days have been set aside throughout the week to mark special aspects of the Office of Civilian Defense, Office of Emergency Management (OEM). From an actual photograph. It is being distributed by state and local defense throughout the nation. Poster designed by Herbert Matter, distributed by the Office of Civilian Defense. It is printed in four colors. Copies may be obtained from state and local councils', 'IMG01', 'PC02', 'World War public-information and propaganda posters', 'proposed_new_cell', 'high', 'keyword_rule', '\bCivilian Defense\b; \bdefense poster\b; \bOffice of War Information\b; \bOffice of Emergency Management\b', 'Create or confirm a public-information/war-propaganda poster cell.') on conflict ("capture_id") do update set "source_id" = excluded."source_id", "source_name" = excluded."source_name", "source_title" = excluded."source_title", "image_presence_code" = excluded."image_presence_code", "assigned_cell_id" = excluded."assigned_cell_id", "assigned_cell_name" = excluded."assigned_cell_name", "assignment_type" = excluded."assignment_type", "assignment_confidence" = excluded."assignment_confidence", "assignment_basis" = excluded."assignment_basis", "matched_terms" = excluded."matched_terms", "recommended_next_step" = excluded."recommended_next_step";
